import math


class Group:
    def __init__(self, members: list[str]) -> None:
        if not members or len(set(members)) != len(members):
            raise ValueError("Members must be nonempty and unique")
        self._members = tuple(members)
        self._balances = {member: 0.0 for member in members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        if not math.isfinite(amount) or amount <= 0:
            raise ValueError("Amount must be positive and finite")
        if payer not in self._balances:
            raise ValueError("Payer is not a group member")

        people = self._members if participants is None else tuple(participants)
        if not people or len(set(people)) != len(people):
            raise ValueError("Participants must be nonempty and unique")
        if any(person not in self._balances for person in people):
            raise ValueError("Participant is not a group member")

        share = amount / len(people)
        self._balances[payer] += amount
        for person in people:
            self._balances[person] -= share

    def balances(self) -> dict[str, float]:
        return self._balances.copy()

    def settle_up(self) -> list[tuple[str, str, float]]:
        debtors = [
            [member, -balance]
            for member, balance in self._balances.items()
            if balance < 0
        ]
        creditors = [
            [member, balance]
            for member, balance in self._balances.items()
            if balance > 0
        ]
        payments = []
        i = j = 0

        while i < len(debtors) and j < len(creditors):
            debtor, debt = debtors[i]
            creditor, credit = creditors[j]

            if debt < 1.0:
                i += 1
                continue
            if credit < 1.0:
                j += 1
                continue

            amount = min(debt, credit)
            payments.append((debtor, creditor, amount))

            if debt == amount:
                i += 1
            else:
                debtors[i][1] = debt - amount

            if credit == amount:
                j += 1
            else:
                creditors[j][1] = credit - amount

        return payments
